  // Marca el material introductorio existente con grado y unidad sin sustituirlo.
  for (const [curso, filas] of Object.entries(existentes)) {
    for (const [id, grado, unidad] of filas) {
      const tema = catalogo[curso]?.find(item => item.id === id);
      if (tema) Object.assign(tema, { grado, unidad, competencia: competencia[curso] });
    }
  }
  for (const [curso, temas] of Object.entries(extras)) {
    catalogo[curso] = [...(catalogo[curso] || []), ...temas]
      .sort((a, b) => (a.grado || 1) - (b.grado || 1) || a.unidad.localeCompare(b.unidad, 'es'));
  }

