      'composicion-contraste': { teoria: [['Idea clave','La composición organiza elementos visuales en un espacio. El equilibrio distribuye el peso visual y el contraste hace visibles las diferencias.'],['Ejemplo para comprender','Una figura clara sobre un fondo oscuro destaca gracias al contraste.']], practica: ['¿Para qué puede usar el contraste un artista?',['Para destacar un elemento','Para ocultar todas las formas','Para quitar significado','Para medir el sonido'],0,'El contraste ayuda a dirigir la mirada hacia un elemento.'] },
      'teatro-accion-escena': { teoria: [['Idea clave','Una escena presenta una situación mediante personajes, acciones y diálogos. El objetivo de un personaje ayuda a entender por qué actúa o habla.'],['Ejemplo para comprender','En una escena breve, un estudiante quiere devolver un cuaderno perdido y encuentra un obstáculo.']], practica: ['¿Qué ayuda a comprender las acciones de un personaje?',['Su objetivo o necesidad','El número de página','Solo la paleta de colores','La escala de un mapa'],0,'El objetivo del personaje explica sus decisiones.'] },
      'arte-tradicion-amazonia': { teoria: [['Idea clave','Las prácticas artísticas transmiten memorias y saberes de las comunidades. Para comprenderlas se escucha a quienes las mantienen y se reconoce su autoría.'],['Ejemplo para comprender','Antes de adaptar un diseño local, averigua su significado y pregunta si se permite usarlo.']], practica: ['¿Qué demuestra respeto por una práctica cultural?',['Conocer su contexto y reconocer a sus creadores','Copiarla sin preguntar','Cambiarle el nombre','Tratar todas las tradiciones como iguales'],0,'Conocer el contexto y reconocer a sus autores respeta a la comunidad.'] },
      'analisis-elementos-artisticos': { teoria: [['Idea clave','La apreciación crítica describe elementos, considera el contexto y explica cómo las decisiones comunican significado. Una interpretación debe apoyarse en evidencias de la obra.'],['Ejemplo para comprender','En un afiche, observa el color, las imágenes y el texto antes de explicar cómo busca convencer.']], practica: ['¿Qué sustenta una interpretación de una obra?',['Elementos observables y contexto','Una suposición sin evidencias','Solo su precio','La edad del artista'],0,'La interpretación se fortalece al relacionarse con rasgos visibles o audibles de la obra.'] },
      'planificacion-obra-colectiva': { teoria: [['Idea clave','Un plan creativo define intención, público, materiales, etapas y medidas de seguridad. Los bocetos y las pruebas permiten anticipar cambios.'],['Ejemplo para comprender','Un grupo puede dibujar el diseño de un mural y probar la pintura en una muestra pequeña.']], practica: ['¿Qué conviene hacer antes de pintar un mural grande?',['Acordar un plan y probar los materiales','Pintar sin conversar sobre la idea','Ignorar el estado de la pared','Omitir la seguridad'],0,'Planificar y probar reduce problemas durante un proyecto compartido.'] },
      'arte-digital-medios': { teoria: [['Idea clave','Las herramientas digitales son recursos artísticos. Elegir un medio requiere considerar la intención, el público, el acceso, la autoría y la forma de compartir la obra.'],['Ejemplo para comprender','Un estudiante puede registrar un proceso con el teléfono y ordenar las imágenes para contar una historia.']], practica: ['¿Qué orienta la elección de un medio artístico?',['El propósito y el público de la obra','Solo la herramienta más nueva','Únicamente el tamaño del archivo','Una elección al azar'],0,'El medio debe ayudar a cumplir la intención de la obra y comunicarse con su público.'] },
      'exhibicion-curaduria': { teoria: [['Idea clave','Curar una muestra consiste en seleccionar y organizar obras alrededor de una idea. Las etiquetas y un recorrido claro ayudan al público a comprender sus relaciones.'],['Ejemplo para comprender','Una exposición pequeña puede agrupar obras por tema e incluir una nota sobre el proceso de cada una.']], practica: ['¿Qué hace quien organiza la curaduría de una muestra?',['Selecciona y organiza obras para comunicar una idea','Modifica todas las obras','Quita el nombre de sus autores','Evalúa al público'],0,'La curaduría selecciona y organiza obras para comunicar una idea.'] }
